      if (n.sub && !big && textPx(n.sub, 12, false) > avail * 1.03) rep.warn(`node '${n.id}': subtitle will be cut off with '…' (~${Math.round(textPx(n.sub, 12, false))}px > ${Math.round(avail)}px)`);
